classdef SolverTest < matlab.unittest.TestCase
    properties (TestParameter)
        tol = {1e-6, 1e-10};
    end
    methods (Test)
        function testRoot(testCase, tol)
            r = fzero(@(x) x^2 - 4, [1 3]);
            testCase.verifyEqual(r, 2, 'AbsTol', tol);
        end
        function testError(testCase)
            testCase.verifyError(@() fzero(@(x) x^2 + 1, [1 3]), ...
                'MATLAB:fzero:ValuesAtEndPtsSameSign');
        end
    end
end
