function testIntegration(testCase)
    actual = integral(@(x) exp(-x.^2), 0, Inf);
    expected = sqrt(pi)/2;
    testCase.verifyEqual(actual, expected, 'RelTol', 1e-10, ...
        'Gaussian integral should equal sqrt(pi)/2');
    testCase.verifyEqual(size(zeros(3,4)), [3 4]);
end

function testValidation(testCase)
    testCase.verifyError(@() myfunc(-1), 'myfunc:negativeInput');
    testCase.verifyError(@() ones(2,2) * ones(3,3), ...
        'MATLAB:innerdim', 'Dimension mismatch must be caught');
    testCase.verifyWarning(@() myfunc(0), 'myfunc:zeroInput');
end

function testProperties(testCase)
    A = magic(4);
    testCase.verifyTrue(all(sum(A,1) == sum(A,2)'), ...
        'Magic square rows and columns must have equal sums');
    testCase.verifyTrue(isa(A, 'double'), 'magic must return doubles');
    % Clearer alternative:
    testCase.verifyGreaterThan(det(A'*A), -eps);
end

function testPipeline(testCase)
    data = loadTestData();
    testCase.assertEqual(size(data), [100 5], ...
        'Test data must be 100x5 or the rest of this test is invalid');
    result = process(data);
    testCase.verifyEqual(size(result), [100 1]);
    testCase.verifyGreaterThanOrEqual(min(result), 0);
end

