function y = smoothSignal(x, windowLen)
    validateattributes(x, {'numeric'}, {'vector','real','finite','nonempty'}, ...
        mfilename, 'x', 1);
    validateattributes(windowLen, {'numeric'}, ...
        {'scalar','integer','positive','odd','<=', numel(x)}, ...
        mfilename, 'windowLen', 2);
    y = movmean(x, windowLen);
end

function C = safeMultiply(A, B)
    assert(size(A, 2) == size(B, 1), 'myLib:dimMismatch', ...
        'Inner dimensions must agree: got %d and %d.', size(A,2), size(B,1));
    C = A * B;
    assert(all(isfinite(C(:))), 'myLib:nonFinite', ...
        'Result contains non-finite values.');
end

function y = filterSignal(x, cutoff, opts)
    arguments
        x (:,1) double {mustBeFinite, mustBeNonempty}
        cutoff (1,1) double {mustBePositive, mustBeLessThan(cutoff, 0.5)}
        opts.Order (1,1) double {mustBeInteger, mustBePositive} = 4
        opts.Type (1,1) string {mustBeMember(opts.Type, ["low","high"])} = "low"
        opts.ZeroPhase (1,1) logical = true
    end
    [b, a] = butter(opts.Order, cutoff, char(opts.Type));
    if opts.ZeroPhase
        y = filtfilt(b, a, x);
    else
        y = filter(b, a, x);
    end
end
